using System;using System.IO;using System.Linq;using System.Text;using System.Xml;using System.Threading.Tasks;using BeamScheduleFormatter;
class PowLargeWorkbookTests {
 static int checks;static void Check(bool ok,string message){checks++;if(!ok)throw new Exception(message);}static void Reject(Action work,string message){bool rejected=false;try{work();}catch{rejected=true;}Check(rejected,message);}
 static void Main(){Run().GetAwaiter().GetResult();}
 static async Task Run(){string dir=Path.Combine(Path.GetTempPath(),"DTCE-large-workbook-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{string original=Path.Combine(dir,"Large workbook.xlsm"),saved=Path.Combine(dir,"Project.pow.xml");long length=129L*1024*1024+7;using(var file=new FileStream(original,FileMode.Create)){file.SetLength(length);file.WriteByte(80);file.Position=length-1;file.WriteByte(75);}var sources=new PowSourceFiles();bool connected=false;string warning=await PowWorkbookLink.Start(()=>{sources.CaptureFile(original,"Excel workbook (imported original)");return Task.FromResult(true);},()=>{connected=true;return Task.FromResult(true);});Check(connected&&warning=="","129 MiB workbook snapshot does not block the link or hit old 32/128 MiB limits");Check(sources.Files.Single().Size==length,"Actual long file size retained");string hash=sources.Files.Single().Sha256;File.Delete(original);var doc=new XmlDocument();doc.LoadXml("<ProgramOfWorks version='21'><Title>Large attachment test</Title></ProgramOfWorks>");sources.Write(doc.DocumentElement,true);PowProjectFileWriter.WriteWithSources(saved,doc.OuterXml,sources);var opened=PowProjectFileWriter.Read(saved);var copy=opened.Sources.Files.Single();Check(copy.Size==length&&copy.Sha256==hash,"Streaming full POW save/open verifies exact large original after source removal");Check(opened.Document.DocumentElement["SourceFiles"]==null&&opened.Document.DocumentElement["Title"].InnerText=="Large attachment test","Loaded calculation XML excludes attachment payloads from memory");using(var input=copy.OpenRead()){Check(input.ReadByte()==80,"Original first byte retained");input.Position=length-1;Check(input.ReadByte()==75,"Original final byte retained");}copy.CopyTo(original);Check(new FileInfo(original).Length==length,"Original copy export streams the full file");for(int n=0;n<300;n++)sources.Add(new PowSourceFile("Reference "+n+".txt","Project attachment",Encoding.UTF8.GetBytes("same content")));Check(sources.Files.Count==301,"No old 256-file count limit");
 connected=false;warning=await PowWorkbookLink.Start(()=>{throw new IOException("Read denied by workbook lock");},()=>{connected=true;return Task.FromResult(true);});Check(connected&&warning.Contains("workbook lock"),"Attachment IO failure is reported separately while linking continues");Reject(()=>PowWorkbookLink.Start(()=>Task.FromResult(true),()=>{throw new Exception("Actual Excel connection failed");}).GetAwaiter().GetResult(),"Real connection failure is still surfaced");byte[] before=File.ReadAllBytes(saved);Reject(()=>PowProjectFileWriter.AtomicWrite(saved,output=>{output.WriteByte(1);throw new IOException("Disk failure");}),"Interrupted streaming save is reported");Check(File.ReadAllBytes(saved).SequenceEqual(before)&&Directory.GetFiles(dir,"*.tmp").Length==0,"Interrupted streaming save retains prior POW without temporary residue");var bad=new XmlDocument();bad.LoadXml("<ProgramOfWorks><SourceFiles version='1'><File id='x' name='bad.xlsm' kind='Excel workbook' sha256='x' size='1' recoveredText='False' encoding='gzip-base64'>H4sIAAAAAAAEA2NkAgCSQsy2AgAAAA==</File></SourceFiles></ProgramOfWorks>");Reject(()=>PowSourceFiles.Read(bad.DocumentElement),"Integrity/decompression checks remain when fixed size limits are removed");
 Console.WriteLine("PASS: "+checks+" unlimited streaming workbook, archive, link isolation and atomic failure checks");}finally{Directory.Delete(dir,true);}}
}
